cat > /tmp/BlueskyUITest.swift << 'EOF'
import XCTest

class BlueskyUITest: XCTestCase {
    var app: XCUIApplication!

    override func setUp() {
        super.setUp()
        app = XCUIApplication()
        app.launch()
    }

    func testMuteAccount() {
        // Wait for app to load
        sleep(2)

        // Tap search icon (should be in tab bar)
        let searchButton = app.buttons["Search"]
        if searchButton.exists {
            searchButton.tap()
        }

        sleep(1)

        // Type username in search
        let searchField = app.searchFields.firstMatch
        if searchField.exists {
            searchField.tap()
            searchField.typeText("loudspammer.test")

            sleep(2)

            // Tap on the account in search results
            let accountCell = app.cells.containing(.staticText, identifier: "loudspammer.test").firstMatch
            if accountCell.exists {
                accountCell.tap()
                sleep(2)

                // Tap the ... menu button
                let menuButton = app.buttons["More"]
                if menuButton.exists {
                    menuButton.tap()
                    sleep(1)

                    // Tap mute option
                    let muteButton = app.buttons["Mute loudspammer.test"]
                    if muteButton.exists {
                        muteButton.tap()
                    }
                }
            }
        }
    }
}
